-- PACK-23: an approved stock adjustment (a physical count's variance written off or taken in, a revaluation) is posted to the ledger, so the
-- inventory control account stays equal to the stock ledger value. The flag (off) decides whether inv publishes inv.adjustment.posted; the
-- accounts and the two default rules only act on that event. ADR-786.
INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, enabled, created_by, source_type)
VALUES ('ff.inv.pack23', 'Stock adjustments posted to the ledger; inventory reconciliation and material wastage (PACK-23)', 0, 0, 'migration', 'reference_seed');
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT NULL, a.group_id, '560040', 'Inventory shortage and write-off on verification', 'GENERAL', 'DR', 'INR', 0, NULL, 0, 'migration', 'inv_pack23' FROM fin_accounts a WHERE a.company_id IS NULL AND a.code = '560005' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id IS NULL AND x.code = '560040');
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT a.company_id, a.group_id, '560040', 'Inventory shortage and write-off on verification', 'GENERAL', 'DR', 'INR', 0, NULL, 0, 'migration', 'inv_pack23' FROM fin_accounts a WHERE a.company_id IS NOT NULL AND a.code = '560005' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id = a.company_id AND x.code = '560040');
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT NULL, a.group_id, '420021', 'Inventory excess found on verification', 'REVENUE', 'CR', 'INR', 0, NULL, 0, 'migration', 'inv_pack23' FROM fin_accounts a WHERE a.company_id IS NULL AND a.code = '420001' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id IS NULL AND x.code = '420021');
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT a.company_id, a.group_id, '420021', 'Inventory excess found on verification', 'REVENUE', 'CR', 'INR', 0, NULL, 0, 'migration', 'inv_pack23' FROM fin_accounts a WHERE a.company_id IS NOT NULL AND a.code = '420001' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id = a.company_id AND x.code = '420021');
