 (NULL, 'PRL/P2301', 'ADJ-LOSS', 'inv.adjustment.posted', 'Stock adjustment: shortage written off out of inventory', 'POST', NULL, 100, '[{"field": "kind", "op": "eq", "value": "LOSS"}]', '[{"side": "DR", "account": "560040", "amount": "value", "dims": {"projectId": "storeProjectId", "siteId": "storeSiteId"}}, {"side": "CR", "account": "130001", "amount": "value", "dims": {"projectId": "storeProjectId", "siteId": "storeSiteId"}}]', 'Stock adjustment {docNo}', 'JV', 1, '2026-04-01', 'APPROVED', 'Default rule of PACK-23 (ADR-786)', 'system', 'system', '2026-11-28T00:00:00.000Z', 'migration', 'reference_seed'),
